package org.echogesture.finalapp

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * JVM parity against a fixture produced by REAL TFLite inference.
 *
 * `parity_ensemble_runtime.txt` was generated by the Python reference path on
 * the real clip .../0283886564670357-WHAT FOR.mp4 using the shipped member
 * bytes and `ai_edge_litert` 2.3.0 (see the fixture's `# producer` header):
 *   features (hash pinned in the header) -> every member's raw logits ->
 *   numpy mean -> one softmax -> top-5.
 *
 * This test does NOT claim to run TFLite on the JVM: the tensorflow-lite AAR
 * ships Android ABIs only and the JVM unit-test runtime fails with
 * `UnsatisfiedLinkError: no tensorflowlite_jni` (that is also why the on-device
 * test TfliteEnsembleInferenceTest exists). What it DOES pin is everything
 * between the raw logits and the result the user sees: the exact dequantize /
 * mean / softmax / top-k arithmetic of [LandmarkClassifier.invoke] and
 * [LandmarkClassifier.predict], reproducing each member's real logits from
 * the fixture and requiring the same top-5 and confidence.
 *
 * Tolerances and why:
 *  - per-member logits: 1e-5. Fixture values are float32 printed from real
 *    TFLite output; parsing and the (possibly no-op) dequantize are float32
 *    operations, so only last-bit rounding can differ.
 *  - averaged logits: 1e-5 (mean introduces one rounding per element).
 *  - softmax probs: 1e-6 (a single exp/divide chain; the model logit margin
 *    top1-top2 is 3.93, so even a 1e-3 logit perturbation cannot change top-1,
 *    so these tolerances are not hiding numerical drift).
 */
class EnsembleRuntimeParityTest {

    private fun lines(): List<String> =
        javaClass.classLoader!!.getResource("parity_ensemble_runtime.txt")
            ?.readText()
            ?.lineSequence()
            ?.filter { it.isNotBlank() }
            ?.filter { !it.startsWith("#") }
            ?.toList()
            ?: error("missing fixture parity_ensemble_runtime.txt")

    private fun floats(line: String, n: Int): FloatArray {
        val v = line.trim().split(' ').filter { it.isNotEmpty() }
        assertEquals("float count", n, v.size)
        return FloatArray(n) { v[it].toFloat() }
    }

    @Test
    fun realMemberLogitsReproducePythonThroughProductionArithmetic() {
        val l = lines()
        val (members, classes) = l[0].split(' ').let { it[0].toInt() to it[1].toInt() }
        assertEquals(4, members)
        assertEquals(100, classes)
        val names = l[1].trim().split(' ')
        assertEquals(
            listOf(
                "landmark_ens_tcn21_fp16.tflite",
                "landmark_ens_tcnm61_fp16.tflite",
                "landmark_ens_tcnm62_fp16.tflite",
                "landmark_ens_rob71_fp16.tflite"
            ),
            names
        )
        val memberLogits = Array(members) { floats(l[2 + it], classes) }
        val expectedAvg = floats(l[2 + members], classes)
        val expectedProbs = floats(l[3 + members], classes)
        val expectedTop = l[4 + members].trim().split(' ').map { it.toInt() }
        val expectedLabels = l[5 + members].trim().split(' ')
        val expectedConfidence = l[6 + members].trim().toFloat()
        val vocabulary = l[7 + members].trim().split(' ')
        assertEquals(classes, vocabulary.size)

        // The exact member set the fixture proves was invoked: the four real
        // binaries are materially different models (pairwise max |delta| > 2.2),
        // so they cannot be one model copied four times.
        val ordered = memberLogits.sortedBy { it[0] }
        for (i in memberLogits.indices) for (j in i + 1 until memberLogits.size) {
            var d = 0f
            for (c in 0 until classes) d = maxOf(d, kotlin.math.abs(memberLogits[i][c] - memberLogits[j][c]))
            assertTrue("members $i/$j are identical; fixture is not four real models", d > 0.5f)
        }
        assertEquals("member logits must stay distinct", ordered.size, memberLogits.size)

        // Production aggregation: mean -> ONE softmax -> top-5.
        val avg = EnsembleAggregation.meanLogits(memberLogits)
        assertArrayEquals("mean logits drift from numpy mean", expectedAvg, avg, 1e-5f)
        val probs = EnsembleAggregation.softmax(avg)
        assertArrayEquals("softmax drift", expectedProbs, probs, 1e-6f)
        val top = EnsembleAggregation.topK(probs, 5)
        assertArrayEquals("top-5 indices drift", expectedTop.toIntArray(), top)
        assertEquals(expectedLabels, top.map { vocabulary[it] })
        assertEquals("top-1", "WHATFOR1", vocabulary[top[0]])
        assertEquals("confidence drift", expectedConfidence, probs[top[0]], 1e-6f)
    }

    @Test
    fun everyMemberAloneWouldPredictTheEnsembleTop1OnThisClip() {
        // All four members independently pick WHATFOR1 (index 8): the fixture is
        // a genuine four-model consensus, and the ensemble confidence (0.8821)
        // is the softmax of the AVERAGE, not any single member's peak.
        val l = lines()
        val classes = l[0].split(' ')[1].toInt()
        val memberLogits = Array(4) { floats(l[2 + it], classes) }
        val confidences = memberLogits.map { m ->
            val p = EnsembleAggregation.softmax(m)
            EnsembleAggregation.topK(p, 1)[0] to p[EnsembleAggregation.topK(p, 1)[0]]
        }
        confidences.forEach { (idx, _) -> assertEquals("every member top-1", 8, idx) }
        // Mean-logit softmax must differ from the mean of per-member softmax
        // probabilities: aggregation is on logits, exactly as src/main.py does.
        val avgConf = EnsembleAggregation.softmax(EnsembleAggregation.meanLogits(memberLogits))[8]
        val meanOfProbs = confidences.map { it.second }.average().toFloat()
        assertTrue(
            "aggregation must be on logits, not probabilities (avg=$avgConf mean-of-probs=$meanOfProbs)",
            kotlin.math.abs(avgConf - meanOfProbs) > 0.01f
        )
    }

    /**
     * Source-only vocabulary check. Reads `models/landmark_labels.json`, parses
     * it through the production vocabulary logic ([ModelContract.parseLabels]),
     * and requires the result to be exactly the frozen class axis the parity
     * fixture was produced against.
     *
     * This deliberately loads NO model weights: the vocabulary is the one piece
     * of the runtime contract that is fully readable from source, so it must be
     * verified on every checkout, including one that has no weights at all. It
     * never skips — a missing or moved labels file is a failure, not an
     * "unavailable".
     */
    @Test
    fun shippedVocabularyMatchesTheFrozenClassAxis() {
        val labelsFile = findRepoFile("models/${ModelContract.LABELS_ASSET}")
        val parsed = ModelContract.parseLabels(labelsFile.readText(Charsets.UTF_8))

        // Contiguous indices 0..99: the class axis the model scores over.
        assertEquals("vocabulary size", 100, parsed.size)
        assertEquals(
            "vocabulary labels must be unique",
            parsed.size,
            parsed.toSet().size
        )

        // The frozen reference: the class axis the parity fixtures were made on.
        val l = lines()
        val classes = l[0].split(' ')[1].toInt()
        val fixtureVocabulary = l[7 + l[0].split(' ')[0].toInt()].trim().split(' ')
        assertEquals("fixture vocabulary size", 100, classes)
        assertEquals(
            "shipped labels must equal the frozen class axis, in order",
            fixtureVocabulary,
            parsed
        )

        // The fixture pins index 8 as WHATFOR1; a re-ordered labels file would
        // change the meaning of every index the model emits.
        assertEquals("WHATFOR1", parsed[8])
    }

    /**
     * A labels file whose indices are not a permutation of 0..99 is rejected,
     * not silently re-sorted. Reads no weights.
     */
    @Test
    fun vocabularyWithADuplicateOrMissingIndexIsRejected() {
        val dup = """{"A":0,"B":0}"""
        val gap = """{"A":0,"B":2}"""
        for (json in listOf(dup, gap)) {
            val err = runCatching { ModelContract.parseLabels(json) }.exceptionOrNull()
            assertTrue(
                "malformed vocabulary must fail, got $err for $json",
                err is IllegalStateException
            )
        }
    }

    private fun findRepoFile(relative: String): java.io.File {
        // Gradle runs unit tests with the module directory as CWD
        // (app/android_final/app), so the repo root is a few levels up.
        var dir = java.io.File(".").absoluteFile
        repeat(6) {
            val candidate = java.io.File(dir, relative)
            if (candidate.isFile) return candidate
            dir = dir.parentFile ?: return@repeat
        }
        throw AssertionError(
            "$relative was not found from ${java.io.File(".").absolutePath}. It is " +
                "tracked source and must be present on every checkout."
        )
    }
}